function 战斗准备类:取巧智魔信息(任务id, 玩家id)
	local 战斗单位 = {
		阵法 = 阵法名称[取随机数(2, #阵法名称)]
	}
	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id) - 5
	local 模型范围 = {
		"野鬼",
		"僵尸",
		"牛头",
		"马面",
		"鬼将",
		"吸血鬼",
		"噬天虎",
		"炎魔神"
	}
	local 怪物名称 = {
		{
			"巧智魔",
			"蜃气妖",
			{
				"感知",
				"夜战",
				"必杀",
				"连击",
				"法术连击",
				"法术暴击"
			},
			Q_门派法术[门派名称[ygsj(#门派名称)]],
			{}
		},
		{
			"妖魔喽啰",
			模型范围[取随机数(1, #模型范围)],
			{
				"连击",
				"必杀",
				"夜战"
			},
			{},
			{
				伤害 = 1.3
			}
		},
		{
			"妖魔喽啰",
			模型范围[取随机数(1, #模型范围)],
			{
				"连击",
				"必杀",
				"夜战"
			},
			{},
			{
				伤害 = 1.3
			}
		},
		{
			"妖魔喽啰",
			模型范围[取随机数(1, #模型范围)],
			{
				"法术连击",
				"夜战",
				"法术暴击",
				"法术波动"
			},
			{
				"水攻",
				"落岩",
				"雷击",
				"烈火"
			},
			{}
		},
		{
			"妖魔喽啰",
			模型范围[取随机数(1, #模型范围)],
			{
				"必杀",
				"夜战"
			},
			夜光随机物理法术(3),
			{}
		},
		{
			"妖魔喽啰",
			模型范围[取随机数(1, #模型范围)],
			{
				"法术连击",
				"敏捷",
				"法术暴击",
				"法术波动"
			},
			夜光随机恢复法术(3),
			{
				速度 = 2.5,
				气血 = 1.5
			}
		},
		{
			"妖魔巫师",
			模型范围[取随机数(1, #模型范围)],
			{
				"高级招架",
				"高级法术抵抗",
				"高级再生",
				"敏捷",
				"神佑复生"
			},
			夜光随机封印法术(3),
			{
				速度 = 3
			}
		}
	}
	local 可选 = {
		3,
		4,
		5,
		6
	}
	位置 = {
		[4] = 夜光随机法术,
		[5] = 夜光随机物理法术,
		[6] = 夜光随机恢复法术
	}

	for n = 1, 8 do
		local i = n

		if i > 7 then
			local aa = ygsj(#可选)
			local bb = 可选[aa]
			怪物名称[i] = 怪物名称[bb]

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end
		end

		if n == 1 then
			战斗单位[n] = {
				愤怒 = 9999,
				饰品 = true,
				变异 = true,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 0.9,
				魔法 = 阶段属性[等级].魔法 * 10,
				伤害 = 阶段属性[等级].伤害 * 0.8,
				灵力 = 阶段属性[等级].法伤 * 0.8,
				速度 = 阶段属性[等级].速度 * 1,
				防御 = 阶段属性[等级].防御 * 0.1,
				法防 = 阶段属性[等级].法防 * 0.1,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
				主动技能 = 怪物名称[i][4]
			}
		else
			战斗单位[n] = {
				愤怒 = 9999,
				变异 = false,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 0.6,
				魔法 = 阶段属性[等级].魔法 * 10,
				伤害 = 阶段属性[等级].伤害 * 0.6,
				灵力 = 阶段属性[等级].法伤 * 0.6,
				速度 = 阶段属性[等级].速度 * 0.5,
				防御 = 阶段属性[等级].防御 * 0.05,
				法防 = 阶段属性[等级].法防 * 0.05,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
				主动技能 = 怪物名称[i][4]
			}
		end

		if not 判断是否为空表(怪物名称[i][5]) then
			for k, v in pairs(怪物名称[i][5]) do
				战斗单位[n][k] = (战斗单位[n][k] or 1) * v
			end
		end
	end

	return 全局战斗难度调整(战斗单位)
end

