function 战斗准备类:取剑会天下BB技能1(属性, 技能)
	local 最高属性 = {
		"力量",
		0
	}

	for n, v in pairs(属性) do
		if 最高属性[2] < v then
			最高属性[1] = n
			最高属性[2] = v
		end
	end

	if 最高属性[2] == 属性.力量 then
		最高属性[1] = "力量"
	end

	if 最高属性[1] == "力量" then
		local 高级技能 = {
			"高级必杀",
			"高级再生",
			"高级幸运",
