function 战斗准备类:取毛贼信息(任务id, 玩家id)
	local 战斗单位 = {
		阵法 = 阵法名称[取随机数(2, #阵法名称)]
	}
	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id) - 5
	local 模型范围 = {
		"山贼",
		"赌徒",
		"强盗"
	}
	local 怪物名称 = {
		{
			"毛贼",
			"强盗",
			{
				"感知",
				"夜战",
				"必杀",
				"连击",
				"法术连击",
				"法术暴击"
			},
			Q_门派法术[门派名称[ygsj(#门派名称)]],
			{}
		},
		{
			"凶兽",
			"老虎",
			{
				"连击",
				"必杀",
				"夜战"
			},
			{},
			{
				伤害 = 1.3
			}
		},
		{
			"打手",
			模型范围[取随机数(1, #模型范围)],
			{
				"连击",
				"必杀",
				"夜战"
			},
			{},
			{
				伤害 = 1.3
			}
		},
		{
			"打手",
			模型范围[取随机数(1, #模型范围)],
			{
				"法术连击",
				"夜战",
				"法术暴击",
				"法术波动"
			},
			{
				"水攻",
				"落岩",
				"雷击",
				"烈火"
			},
			{}
		},
		{
			"打手",
			模型范围[取随机数(1, #模型范围)],
			{
				"必杀",
				"夜战"
			},
			夜光随机物理法术(3),
			{}
		},
		{
			"打手",
			模型范围[取随机数(1, #模型范围)],
			{
				"法术连击",
				"夜战",
				"法术暴击",
				"法术波动"
			},
			夜光随机恢复法术(3),
			{
				速度 = 2.5,
				气血 = 1.5
			}
		}
	}
	local 可选 = {
		3,
		4,
		5,
		6
	}
	位置 = {
		[4] = 夜光随机法术,
		[5] = 夜光随机物理法术,
		[6] = 夜光随机恢复法术
	}

	for n = 1, 8 do
		local i = n

		if i > 6 then
			local aa = ygsj(#可选)
			local bb = 可选[aa]
			怪物名称[i] = 怪物名称[bb]

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end

			table.remove(可选, aa)
		end

		if n == 1 then
			战斗单位[n] = {
				愤怒 = 9999,
				饰品 = true,
				变异 = true,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
