				"高级夜战"
			},
			夜光随机物理法术(3),
			{}
		},
		{
			"孤魂野鬼",
			模型范围[取随机数(1, #模型范围)],
			{
				"高级法术连击",
				"高级敏捷",
				"高级法术暴击",
				"高级法术波动"
			},
			夜光随机恢复法术(3),
			{
				速度 = 2.5,
				气血 = 1.5
			}
		}
	}
	local 可选 = {
		7,
		4,
		5,
		6
	}
	位置 = {
		[5] = 夜光随机法术,
		[6] = 夜光随机物理法术,
		[7] = 夜光随机恢复法术
	}

	for n = 1, 10 do
		local i = n

		if i > 7 then
			local aa = ygsj(#可选)
			local bb = 可选[aa]
			怪物名称[i] = 怪物名称[bb]

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end

			table.remove(可选, aa)
		end

		if n == 1 then
			战斗单位[n] = {
				愤怒 = 9999,
				变异 = true,
				饰品 = true,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 1.5,
