				防御 = 阶段属性[等级].防御 * 0.4,
				法防 = 阶段属性[等级].法防 * 0.6,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
				主动技能 = 怪物名称[i][4],
				攻击修炼 = math.max(qz1(阶段属性[等级].修炼), 1),
				防御修炼 = math.max(qz1(阶段属性[等级].修炼), 1),
				法术修炼 = math.max(qz1(阶段属性[等级].修炼), 1),
				抗法修炼 = math.max(qz1(阶段属性[等级].修炼), 1)
			}
		else
			战斗单位[n] = {
				愤怒 = 9999,
				变异 = false,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 1.1,
