				速度 = 阶段属性[等级].速度 * 0.7,
				防御 = 阶段属性[等级].防御 * 0.3,
				法防 = 阶段属性[等级].法防 * 0.3,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
