function 战斗准备类:出其不意终结者后转(任务id, 玩家id)
	local 战斗单位 = {}
	local 等级 = 180
	战斗单位[1] = {
		愤怒 = 99999,
	--	不可封印 = true,
		变异 = true,
		名称 = "血神龟",
		模型 = 任务数据[任务id].模型,
		模型 = 任务数据[任务id].模型,
		伤害 = 阶段属性[等级].伤害 * 20*3*2.3,
		气血 = 阶段属性[等级].气血 * 20*13*20*2,
		灵力 = 阶段属性[等级].法伤 * 20*3*2.3,
		速度 = 阶段属性[等级].速度 * 20*1.3*2.3,
		防御 = 阶段属性[等级].防御 * 3,
