function 战斗准备类:取门派示威信息(任务id, 玩家id)
	local 战斗单位 = {}
	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id)
	战斗单位[1] = {
		角色 = true,
		名称 = 任务数据[任务id].名称,
		模型 = 任务数据[任务id].模型,
		武器 = 取武器数据(任务数据[任务id].武器, 任务数据[任务id].武器等级),
		伤害 = 阶段属性[等级].伤害 * 0.7,
		气血 = 阶段属性[等级].气血 * 0.7,
		灵力 = 阶段属性[等级].法伤 * 0.7,
		速度 = 阶段属性[等级].速度 * 1,
		防御 = 阶段属性[等级].防御 * 0.2,
		法防 = 阶段属性[等级].法防 * 0.3,
		躲避 = 阶段属性[等级].躲避 / 2,
		魔法 = 阶段属性[等级].魔法 * 10,
		等级 = 等级,
		攻击修炼 = math.floor(取人物修炼等级上限1(等级)),
		防御修炼 = math.floor(取人物修炼等级上限1(等级)),
		法术修炼 = math.floor(取人物修炼等级上限1(等级)),
		抗法修炼 = math.floor(取人物修炼等级上限1(等级)),
		技能 = {
			"高级感知"
		},
		主动技能 = Q_门派法术[任务数据[任务id].门派]
	}
	local 模型 = 取随机怪(30, 等级)
	战斗单位[2] = {
		角色 = true,
		名称 = "帮凶",
		模型 = 模型[2],
		伤害 = 等级 * 8,
		伤害 = 阶段属性[等级].伤害 * 0.7,
		气血 = 阶段属性[等级].气血 * 0.7,
		灵力 = 阶段属性[等级].法伤 * 0.7,
		速度 = 阶段属性[等级].速度 * 0.5,
		防御 = 阶段属性[等级].防御 * 0.2,
		法防 = 阶段属性[等级].法防 * 0.3,
		躲避 = 阶段属性[等级].躲避 / 2,
		魔法 = 阶段属性[等级].魔法 * 10,
		等级 = 等级,
		攻击修炼 = math.floor(取人物修炼等级上限1(等级)),
		防御修炼 = math.floor(取人物修炼等级上限1(等级)),
		法术修炼 = math.floor(取人物修炼等级上限1(等级)),
		抗法修炼 = math.floor(取人物修炼等级上限1(等级)),
		技能 = {
			"高级感知"
		},
		主动技能 = 取随机法术(3)
	}

	return 全局战斗难度调整(战斗单位)
end

function 战斗准备类:取门派支援信息(任务id, 玩家id)
	local 战斗单位 = {}
	local 模型范围 = {
		"人",
		"魔",
		"仙"
	}

	if 玩家数据[玩家id].角色.数据.种族 == "人" then
		模型范围 = {
			"魔",
			"仙"
		}
	elseif 玩家数据[玩家id].角色.数据.种族 == "魔" then
		模型范围 = {
			"人",
			"仙"
		}
	elseif 玩家数据[玩家id].角色.数据.种族 == "仙" then
		模型范围 = {
			"魔",
			"人"
		}
	end

	模型范围 = 模型范围[取随机数(1, 2)]
	local 模型 = ""

	if 模型范围 == "人" then
		模型 = Q_随机模型[取随机数(1, 5)]
	elseif 模型范围 == "仙" then
		模型 = Q_随机模型[取随机数(6, 10)]
	elseif 模型范围 == "魔" then
		模型 = Q_随机模型[取随机数(11, 15)]
	end

	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id) + 5
	战斗单位[1] = {
		不可封印 = true,
		角色 = true,
		魔法 = 99999900,
		速度 = 0,
		躲避 = 100,
		伤害 = 0,
		名称 = "敌人",
		模型 = 模型,
		气血 = qz(等级 * 60),
		灵力 = 等级 * 4,
		防御 = 等级 * 4,
		法防 = 等级 * 1.5,
		等级 = 等级,
		技能 = {
			"高级感知"
		},
		攻击修炼 = math.floor(取人物修炼等级上限1(等级)),
		防御修炼 = math.floor(取人物修炼等级上限1(等级)),
		法术修炼 = math.floor(取人物修炼等级上限1(等级)),
		抗法修炼 = math.floor(取人物修炼等级上限1(等级)),
		主动技能 = {}
	}

	return 全局战斗难度调整(战斗单位)
end

function 战斗准备类:取门派闯关信息(任务id, 玩家id)
	local 任务id1 = 玩家数据[玩家id].角色:取任务(107)
	local 战斗单位 = {}
	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id)
	战斗单位[1] = {
		愤怒 = 9999,
		角色 = true,
		名称 = 任务数据[任务id].名称,
		模型 = 任务数据[任务id].模型,
		武器 = 取武器数据(Q_闯关数据[Q_门派编号[任务数据[任务id].序列]].武器.名称, 120),
		气血 = 阶段属性[等级].气血 * 1.2,
		魔法 = 阶段属性[等级].魔法 * 10,
		伤害 = 阶段属性[等级].伤害 * 1.15,
		灵力 = 阶段属性[等级].法伤 * 1.2,
		速度 = 阶段属性[等级].速度 * 1.3,
		防御 = 阶段属性[等级].防御 * 0.3,
		法防 = 阶段属性[等级].法防 * 0.3,
		躲避 = 阶段属性[等级].躲避 * 0.5,
		等级 = 等级,
		攻击修炼 = math.floor(取人物修炼等级上限1(等级)),
		防御修炼 = math.floor(取人物修炼等级上限1(等级)),
		法术修炼 = math.floor(取人物修炼等级上限1(等级)),
		抗法修炼 = math.floor(取人物修炼等级上限1(等级)),
		技能 = {
			"高级感知"
		},
		主动技能 = Q_门派法术1[Q_门派编号[任务数据[任务id].序列]]
	}
	local 数量 = 6 + 15 - #任务数据[任务id1].闯关序列

	if 数量 > 10 then
		数量 = 10
	end

	for n = 2, 数量 do
		local aa = Q_门派法术1[Q_门派编号[任务数据[任务id].序列]]

		if ygsj() <= 20 then
			aa = {}
		end

		战斗单位[n] = {
			愤怒 = 9999,
			名称 = Q_门派编号[任务数据[任务id].序列] .. "弟子",
			模型 = Q_闯关数据[Q_门派编号[任务数据[任务id].序列]].弟子[取随机数(1, #Q_闯关数据[Q_门派编号[任务数据[任务id].序列]].弟子)],
			气血 = 阶段属性[等级].气血 * 0.8,
			魔法 = 阶段属性[等级].魔法 * 10,
			伤害 = 阶段属性[等级].伤害 * 0.85,
			灵力 = 阶段属性[等级].法伤 * 1,
			速度 = 阶段属性[等级].速度 * 0.5,
			防御 = 阶段属性[等级].防御 * 0.15,
			法防 = 阶段属性[等级].法防 * 0.15,
			躲避 = 阶段属性[等级].躲避 * 0.5,
			等级 = 等级,
			攻击修炼 = math.floor(取人物修炼等级上限1(等级)),
			防御修炼 = math.floor(取人物修炼等级上限1(等级)),
			法术修炼 = math.floor(取人物修炼等级上限1(等级)),
			抗法修炼 = math.floor(取人物修炼等级上限1(等级)),
			技能 = {
				"高级感知"
			},
			主动技能 = aa
		}
	end

	return 全局战斗难度调整(战斗单位)
end

