			},
			主动技能 = {}
		}
	end

	return 全局战斗难度调整(战斗单位)
end

function 战斗准备类:取封妖任务信息(任务id, 玩家id)
	local 战斗单位 = {}
	local 等级 = 取平均阶段等级(玩家id)
	战斗单位[1] = {
		名称 = 任务数据[任务id].名称,
		模型 = 任务数据[任务id].模型,
		伤害 = 阶段属性[等级].伤害 * 1,
		气血 = 阶段属性[等级].气血 * 1.1,
		灵力 = 阶段属性[等级].法伤 * 1,
		速度 = 阶段属性[等级].速度 * 1.1,
		防御 = 阶段属性[等级].防御 * 0.2,
		法防 = 阶段属性[等级].法防 * 0.2,
		躲避 = 阶段属性[等级].躲避,
		魔法 = 阶段属性[等级].魔法 * 10,
		等级 = 等级,
		技能 = {
			"高级感知"
		},
		主动技能 = 取随机法术(3)
	}
	local 数量 = 取队伍人数(玩家id)
	数量 = 数量 + 3
	local 等级 = 取平均阶段等级(玩家id)

	for n = 1, 数量 do
		local 模型 = 取随机怪(任务数据[任务id].等级, 任务数据[任务id].等级)
		战斗单位[n + 1] = {
			名称 = 模型[2] .. "喽罗",
			模型 = 模型[2],
			伤害 = 阶段属性[等级].伤害 * 0.75,
			气血 = 阶段属性[等级].气血 * 0.8,
			灵力 = 阶段属性[等级].法伤 * 0.8,
			速度 = 阶段属性[等级].速度 * 0.4,
			防御 = 阶段属性[等级].防御 * 0.1,
			法防 = 阶段属性[等级].法防 * 0.1,
			躲避 = 阶段属性[等级].躲避,
			魔法 = 阶段属性[等级].魔法 * 10,
			等级 = 等级,
			技能 = {
				"高级感知"
			},
			主动技能 = 取随机法术(2)
		}
	end

	if 取随机数() <= 30 then
		战斗单位[#战斗单位].变异 = true
		战斗单位[#战斗单位].名称 = "变异" .. 战斗单位[#战斗单位].模型
		战斗单位[#战斗单位].主动技能 = {
			"失心符"
		}
		战斗单位[#战斗单位].伤害 = 1
		战斗单位[#战斗单位].法防 = 等级 * 0.5
		战斗单位[#战斗单位].速度 = 等级 * 50
		战斗单位[#战斗单位].气血 = 战斗单位[#战斗单位].气血 * 10
	end

	return 全局战斗难度调整(战斗单位)
end

