			模型范围[取随机数(1, #模型范围)],
			{
				"高级法术连击",
				"高级敏捷",
				"高级法术暴击",
				"高级法术波动"
			},
			夜光随机恢复法术(3),
			{
				速度 = 2.5,
				气血 = 1.5
			}
		},
		{
			"帮凶",
			模型范围[取随机数(1, #模型范围)],
			{
				"高级法术抵抗",
				"高级再生",
				"敏捷",
				"神佑复生"
			},
			夜光随机封印法术(3),
			{
				速度 = 3
			}
		}
	}
	local 可选 = {
		3,
		5,
		4,
		7
	}
	位置 = {
		[4] = 夜光随机法术,
		[5] = 夜光随机物理法术,
		[7] = 夜光随机封印法术
	}

	for n = 1, 10 do
		local i = n

		if i > 7 then
			local aa = ygsj(#可选)
			local bb = 可选[aa]
			怪物名称[i] = 怪物名称[bb]

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end

			table.remove(可选, aa)
		end

		if n == 1 then
			战斗单位[n] = {
				愤怒 = 9999,
				变异 = true,
				饰品 = true,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 1.5,
				魔法 = 阶段属性[等级].魔法 * 10,
				伤害 = 阶段属性[等级].伤害 * 1.1,
				灵力 = 阶段属性[等级].法伤 * 1.3,
				速度 = 阶段属性[等级].速度 * 1.5,
				防御 = 阶段属性[等级].防御 * 0.5,
				法防 = 阶段属性[等级].法防 * 0.7,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
				主动技能 = 怪物名称[i][4],
				攻击修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1),
				防御修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1),
				法术修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1),
				抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1)
			}
		else
			战斗单位[n] = {
				愤怒 = 9999,
				变异 = false,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 1,
				魔法 = 阶段属性[等级].魔法 * 10,
				伤害 = 阶段属性[等级].伤害 * 0.9,
				灵力 = 阶段属性[等级].法伤 * 1,
				速度 = 阶段属性[等级].速度 * 0.65,
				防御 = 阶段属性[等级].防御 * 0.3,
				法防 = 阶段属性[等级].法防 * 0.5,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
				主动技能 = 怪物名称[i][4],
				攻击修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1),
				防御修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1),
				法术修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1),
				抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1)
			}
		end

		if not 判断是否为空表(怪物名称[i][5]) then
			for k, v in pairs(怪物名称[i][5]) do
				战斗单位[n][k] = (战斗单位[n][k] or 1) * v
			end
		end
	end

	return 全局战斗难度调整(战斗单位)
end

