function 战斗准备类:取门派入侵(任务id, 玩家id)
	local 战斗单位 = {}
	local 等级 = qz2(玩家数据[玩家id].角色.数据.等级 / 10) * 10
	local 位置 = {
		[2] = 夜光随机法术,
		[4] = 夜光随机物理法术,
		[7] = 夜光随机恢复法术,
		[6] = 夜光随机封印法术
	}
	local 怪物名称 = {
		{
			任务数据[任务id].名称,
			任务数据[任务id].模型,
			{
				"夜战",
				"连击",
				"必杀"
			},
			{},
			{}
		},
		{
			"帮手",
			"强盗",
			{
				"法术连击",
				"夜战",
				"法术暴击",
				"法术波动"
			},
			小法技能,
			{}
		},
		{
			"帮手",
			"山贼",
			{
				"连击",
				"必杀",
				"夜战"
			},
			{},
			{}
		}
	}
	local 可选 = {
		2,
		3
	}
	local 队伍人数 = 取队伍人数(玩家id)

	for n = 1, 队伍人数 * 2 do
		local i = n

		if i > 3 then
			local aa = ygsj(#可选)
			local bb = 可选[aa]
			怪物名称[i] = 怪物名称[bb]

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end
		end

		战斗单位[n] = {
			愤怒 = 9999,
			变异 = false,
			名称 = 怪物名称[i][1],
			模型 = 怪物名称[i][2],
			伤害 = 阶段属性[等级].伤害 * 0.6,
			气血 = 阶段属性[等级].气血 * 0.6,
			灵力 = 阶段属性[等级].法伤 * 0.6,
			速度 = 阶段属性[等级].速度 * 0.5,
			防御 = 阶段属性[等级].防御 * 0.1,
			法防 = 阶段属性[等级].法防 * 0.1,
			躲避 = 阶段属性[等级].躲避,
			魔法 = 阶段属性[等级].魔法 * 10,
			等级 = 等级,
			技能 = 怪物名称[i][3],
			主动技能 = 怪物名称[i][4]
		}
		战斗单位[1].气血 = 阶段属性[等级].气血 * 0.8

		if not 判断是否为空表(怪物名称[i][5]) then
			for k, v in pairs(怪物名称[i][5]) do
				战斗单位[n][k] = (战斗单位[n][k] or 1) * v
			end
		end
	end

	return 全局战斗难度调整(战斗单位)
end

