				"法术波动",
				"神佑复生"
			},
			夜光随机恢复法术(3),
			{
				速度 = 1.5
			}
		}
	}
	local 可选 = {
		2,
		3,
		4,
		6,
		7
	}

	for n = 1, 取随机数(8, 10) do
		local i = n

		if i > 7 then
			local aa = ygsj(#可选)
			local bb = 可选[aa]
			怪物名称[i] = 怪物名称[bb]

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end

			table.remove(可选, aa)
		end

		if n == 1 then
			战斗单位[n] = {
				愤怒 = 9999,
				变异 = false,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 3,
				魔法 = 阶段属性[等级].魔法 * 20,
				伤害 = 阶段属性[等级].伤害 * 1.5,
				灵力 = 阶段属性[等级].法伤 * 1.6,
				速度 = 阶段属性[等级].速度 * 1.7,
				防御 = 阶段属性[等级].防御 * 0.4,
				法防 = 阶段属性[等级].法防 * 0.4,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
				主动技能 = 怪物名称[i][4],
				攻击修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1),
				防御修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1),
				法术修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1),
				抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 1), 1)
			}
		else
			战斗单位[n] = {
				愤怒 = 9999,
				变异 = false,
				名称 = 怪物名称[i][1],
				模型 = 怪物名称[i][2],
				气血 = 阶段属性[等级].气血 * 1.5,
				魔法 = 阶段属性[等级].魔法 * 10,
				伤害 = 阶段属性[等级].伤害 * 1.05,
				灵力 = 阶段属性[等级].法伤 * 1.15,
				速度 = 阶段属性[等级].速度 * 0.9,
				防御 = 阶段属性[等级].防御 * 0.2,
				法防 = 阶段属性[等级].法防 * 0.2,
				躲避 = 阶段属性[等级].躲避 * 0.5,
				等级 = 等级,
				技能 = 怪物名称[i][3],
				主动技能 = 怪物名称[i][4],
				攻击修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1),
				防御修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1),
				法术修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1),
				抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1)
			}
		end

		if not 判断是否为空表(怪物名称[i][5]) then
			for k, v in pairs(怪物名称[i][5]) do
				战斗单位[n][k] = (战斗单位[n][k] or 1) * v
			end
		end
	end

	战斗单位[1].不可封印 = true
	战斗单位[1].变异 = true
	local aa = ygsj(3)

	if aa == 1 then
		战斗单位[1].物伤减少 = 0.5
		战斗单位[1].法伤减少 = 1.5
	elseif aa == 2 then
		战斗单位[1].物伤减少 = 1.5
		战斗单位[1].法伤减少 = 0.5
	else
		战斗单位[1].物伤减少 = 0.9
		战斗单位[1].法伤减少 = 0.9
	end

	return 全局战斗难度调整(战斗单位)
end

