			抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 3), 2)
		}

		if not 判断是否为空表(怪物名称[i][5]) then
			for k, v in pairs(怪物名称[i][5]) do
				战斗单位[n][k] = (战斗单位[n][k] or 1) * v
			end
		end
	end

	return 全局战斗难度调整(战斗单位)
end

