取十二祖巫属性 = function(关卡)
	local 主 = {}
	local 小 = {}

	if 关卡 == 1 then
		主.气血 = 3
		主.防御 = 0.6
		主.法防 = 0.7
		主.伤害 = 1.15
		小.气血 = 1
		小.防御 = 0.45
		小.法防 = 0.45
		小.伤害 = 0.85
	elseif 关卡 == 2 then
		主.气血 = 4.5
		主.防御 = 0.85
		主.法防 = 0.95
		主.伤害 = 1.3
		小.气血 = 1.5
		小.防御 = 0.6
		小.法防 = 0.6
		小.伤害 = 1
	elseif 关卡 == 3 then
		主.气血 = 6.5
		主.防御 = 1
		主.法防 = 1.1
		主.伤害 = 1.45
		小.气血 = 2.5
		小.防御 = 0.8
		小.法防 = 0.8
		小.伤害 = 1.15
	end

	return 主, 小
end

