			怪物名称[i][1] = 小怪名称[ygsj(#小怪名称)]
			怪物名称[i][2] = 模型库2[ygsj(#模型库2)]

			if 判断是否为空表(怪物名称[i][3]) then
				怪物名称[i][3] = 列表2加入到列表1({
					"感知",
					"夜战"
				}, 取低级要诀(3))
			end

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end
		end

		战斗单位[n] = {
			愤怒 = 99999,
			变异 = false,
			名称 = 怪物名称[i][1],
			模型 = 怪物名称[i][2],
			伤害 = 阶段属性[等级].伤害 * 1,
			气血 = 阶段属性[等级].气血 * 1,
