	战斗单位.阵法 = 阵法名称[取随机数(2, #阵法名称)]
	local 位置 = {
		[2] = 夜光随机法术,
		[4] = 夜光随机物理法术
	}
	local 怪物名称 = {
		{
			任务数据[任务id].名称,
			任务数据[任务id].模型,
			{
				"高级夜战",
				"高级感知",
				"必杀",
				"高级连击",
				"法术连击",
				"法术暴击"
			},
			Q_门派法术.龙宫,
			{}
		},
		{
			"双刃魔君",
			"进阶修罗傀儡鬼",
			{
				"夜战"
			},
			Q_门派法术.凌波城,
			{}
		},
		{
			"凶牙猛虎",
			"噬天虎",
			{
				"超级必杀",
				"夜战"
			},
			Q_门派法术.大唐官府,
			{}
		},
		{
			"遁地奇兽",
			"蜃气妖",
			{
				"超级必杀",
				"夜战"
			},
			Q_门派法术.五庄观,
			{}
		},
		{
			"蒙面罗刹",
			"夜罗刹",
			{
				"神佑复生"
			},
			夜光随机恢复法术(3),
			{
				灵力 = 5,
				法伤减少 = 1.3,
				速度 = 1.5,
				物伤减少 = 0.7
			}
		},
		{
			"诡异巫蝶",
			"进阶蝴蝶仙子",
			{
				"招架",
				"法术抵抗",
				"超级再生"
			},
			夜光随机封印法术(3),
			{
				速度 = 3
			}
		}
	}
	local 可选 = {
		2,
		3,
		4,
		3
	}

	for n = 1, 数量 do
		local i = n

		if i > 6 then
			local aa = ygsj(#可选)
			local bb = 可选[aa]
			怪物名称[i] = 怪物名称[bb]
			怪物名称[i][1] = "妖魔鬼怪"
			怪物名称[i][2] = 模型库2[ygsj(#模型库2)]

			if 判断是否为空表(怪物名称[i][3]) then
				怪物名称[i][3] = 列表2加入到列表1({
					"感知",
					"夜战"
				}, 取低级要诀(3))
			end

			if 位置[bb] == nil then
				怪物名称[i][4] = {}
			else
				怪物名称[i][4] = 位置[bb](3)
			end
		end

		战斗单位[n] = {
			愤怒 = 99999,
			变异 = false,
			名称 = 怪物名称[i][1],
			模型 = 怪物名称[i][2],
			伤害 = 阶段属性[等级].伤害 * 1.4,
			气血 = 阶段属性[等级].气血 * 2.5,
			灵力 = 阶段属性[等级].法伤 * 1.5,
			速度 = 阶段属性[等级].速度 * 1.15,
			防御 = 阶段属性[等级].防御 * 0.5,
			法防 = 阶段属性[等级].法防 * 0.7,
			躲避 = 阶段属性[等级].躲避,
			魔法 = 阶段属性[等级].魔法 * 10,
			等级 = 等级,
			技能 = 怪物名称[i][3],
			主动技能 = 怪物名称[i][4],
			攻击修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 2),
			防御修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 2),
			法术修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 2),
			抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 2),
			抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 2)
		}

		if not 判断是否为空表(怪物名称[i][5]) then
			for k, v in pairs(怪物名称[i][5]) do
				战斗单位[n][k] = (战斗单位[n][k] or 1) * v
			end
		end
	end

	战斗单位[1].气血 = 阶段属性[等级].气血 * 5
	战斗单位[1].伤害 = 阶段属性[等级].伤害 * 1.8
	战斗单位[1].灵力 = 阶段属性[等级].法伤 * 1.8
	战斗单位[1].速度 = 阶段属性[等级].速度 * 2
	战斗单位[1].法防 = 阶段属性[等级].法防 * 1
	战斗单位[1].防御 = 阶段属性[等级].防御 * 0.65
	战斗单位[1].攻击修炼 = math.max(qz1(阶段属性[等级].修炼 / 1.5), 5)
	战斗单位[1].防御修炼 = math.max(qz1(阶段属性[等级].修炼 / 1.5), 5)
	战斗单位[1].法术修炼 = math.max(qz1(阶段属性[等级].修炼 / 1.5), 5)
	战斗单位[1].抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 1.5), 5)
	战斗单位[1].变异 = true

	return 全局战斗难度调整(战斗单位)
end

