	战斗单位[1].防御修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1)
	战斗单位[1].法术修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1)
	战斗单位[1].抗法修炼 = math.max(qz1(阶段属性[等级].修炼 / 2), 1)
