function 战斗准备类:取梦靥夜叉(任务id, id)
	local 阵容 = {
		怪物数据 = {},
		等级 = 取队伍平均等级(玩家数据[id].队伍, id)
	}
	阵容.怪物数据[1] = {
		伤害 = 0.7,
		愤怒 = 9999,
		气血 = 1.5,
		法防 = 0.1,
		变异 = true,
		魔法 = 10,
		躲避 = 1,
		法伤 = 0.7,
		速度 = 1,
		防御 = 0.1,
		名称 = 任务数据[任务id].名称,
		模型 = 任务数据[任务id].模型,
		修炼 = {},
		被动技能 = {
			"高级健壮",
			"敏捷"
		},
		主动技能 = {}
	}
	local aa = ygsj()

	if aa <= 33 then
		阵容.怪物数据[1].特殊标记 = "画魂"
		阵容.怪物数据[1].发言 = "有本事就把喽啰换成同一种类型#28"
		local 模型 = "画魂"
		local 名称 = "画魂夜叉"

		for i = 2, 10 do
			if i == 3 then
				模型 = "幽萤娃娃"
				名称 = "幽萤夜叉"
			elseif i > 3 then
				if ygsj() <= 50 then
					模型 = "幽萤娃娃"
					名称 = "幽萤夜叉"
				else
					模型 = "画魂"
					名称 = "画魂夜叉"
				end
			end

			阵容.怪物数据[i] = {
				伤害 = 0.3,
				愤怒 = 9999,
				气血 = 0.15,
				法防 = 0.1,
				魔法 = 10,
				躲避 = 1,
				不攻击 = 1,
				法伤 = 0.3,
				速度 = 0.1,
				防御 = 0.1,
				名称 = 名称,
				模型 = 模型,
				修炼 = {},
				被动技能 = {
					"夜战",
					"必杀",
					"连击",
					"法术连击",
					"法术暴击"
				},
				主动技能 = {}
			}
		end
	elseif aa <= 66 then
		阵容.怪物数据[1].特殊标记 = "龙龟"
		阵容.怪物数据[1].发言 = "带有宝贝的不要露脸了，小心宝贝被他们抢走！"

		for i = 2, 6 do
			阵容.怪物数据[i] = {
				伤害 = 0.3,
				愤怒 = 9999,
				气血 = 0.15,
				法防 = 0.1,
				魔法 = 10,
				躲避 = 1,
				不攻击 = 1,
				法伤 = 0.3,
				速度 = 0.1,
				模型 = "龙龟",
				名称 = "神气灵龟",
				防御 = 0.1,
				修炼 = {},
				被动技能 = {
					"夜战",
					"必杀",
					"连击",
					"法术连击",
					"法术暴击"
				},
				主动技能 = {}
			}
		end
	else
		阵容.怪物数据[1].特殊标记 = "厉鬼"

		for i = 2, 10 do
			阵容.怪物数据[i] = {
				伤害 = 0.3,
				愤怒 = 9999,
				气血 = 0.15,
				法防 = 0.1,
				魔法 = 10,
				躲避 = 1,
				法伤 = 0.3,
				速度 = 0.1,
				名称 = "万年厉鬼",
				防御 = 0.1,
				模型 = 取随机怪(10, 55)[2],
				修炼 = {},
				被动技能 = {
					"夜战",
					"必杀",
					"连击",
					"法术连击",
					"法术暴击"
				},
				主动技能 = {}
			}
		end
	end

	return 战斗数据标准模板(阵容, id, 任务id)
end

