function 战斗准备类:取捉鬼任务信息(任务id, 玩家id)
	local 战斗单位 = {}
	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id)
	local 血量加成 = 1
	local 法伤减少 = 1
	local 物伤减少 = 1
	local 速度加成 = 1
	local 普攻躲避率 = 0

	if 任务数据[任务id].模型 == "马面" then
		血量加成 = 1.6
		法伤减少 = 0.35
	elseif 任务数据[任务id].模型 == "牛头" then
		血量加成 = 1.6
		物伤减少 = 0.35
	elseif 任务数据[任务id].模型 == "野鬼" then
		物伤减少 = 0.1
		法伤减少 = 0.1
		血量加成 = 0.45
		速度加成 = 0.3
	elseif 任务数据[任务id].模型 == "骷髅怪" then
		普攻躲避率 = 50
		血量加成 = 2.5
	elseif 任务数据[任务id].模型 == "僵尸" then
		血量加成 = 3.5
	end

	战斗单位[1] = {
		愤怒 = 9999,
		名称 = 任务数据[任务id].名称,
		模型 = 任务数据[任务id].模型,
		气血 = 阶段属性[等级].气血 * 1 * 血量加成,
		魔法 = 阶段属性[等级].魔法 * 10,
		伤害 = 阶段属性[等级].伤害 * 0.7,
		灵力 = 阶段属性[等级].法伤 * 0.8,
		速度 = 阶段属性[等级].速度 * 1 * 速度加成,
		防御 = 阶段属性[等级].防御 * 0.15,
		法防 = 阶段属性[等级].法防 * 0.15,
		躲避 = 阶段属性[等级].躲避 * 0.5,
		普攻躲避率 = 普攻躲避率,
		物伤减少 = 物伤减少,
		法伤减少 = 法伤减少,
		等级 = 等级,
		技能 = 取高级要诀(3),
		主动技能 = 夜光随机攻击法术(5)
	}
	local 数量 = 取随机数(5, 8)

	for n = 1, 数量 do
		local 模型 = 取随机怪(任务数据[任务id].等级, 任务数据[任务id].等级)
		战斗单位[n + 1] = {
			愤怒 = 9999,
			名称 = 模型[2] .. "恶鬼",
			模型 = 模型[2],
			气血 = 阶段属性[等级].气血 * 0.35,
			魔法 = 阶段属性[等级].魔法 * 10,
			伤害 = 阶段属性[等级].伤害 * 0.5,
			灵力 = 阶段属性[等级].法伤 * 0.6,
			速度 = 阶段属性[等级].速度 * 0.3,
			防御 = 阶段属性[等级].防御 * 0.1,
			法防 = 阶段属性[等级].法防 * 0.1,
			躲避 = 阶段属性[等级].躲避 * 0.5,
			等级 = 等级,
			技能 = 取低级要诀(3),
			主动技能 = 取随机法术(2)
		}
	end

	if 取随机数() <= 2 then
		战斗单位[#战斗单位] = {
			魔法 = 99999900,
			捉鬼变异 = true,
			变异 = true,
			伤害 = 1,
			名称 = "善良的" .. 任务数据[任务id].模型,
			模型 = 任务数据[任务id].模型,
			气血 = 等级 * 等级 * 0.25 + 500,
			灵力 = 等级 * 4,
			速度 = 等级 * 3,
			防御 = 等级,
			法防 = 等级 * 0.5,
			躲避 = 等级 * 2,
			等级 = 等级,
			技能 = 取低级要诀(3),
			主动技能 = {}
		}
	end

	return 全局战斗难度调整(战斗单位)
end

function 战斗准备类:自动抓鬼(任务id, 玩家id)
