		攻击修炼 = 阶段属性[等级].修炼 / 2,
		防御修炼 = 阶段属性[等级].修炼,
		法术修炼 = 阶段属性[等级].修炼 / 2,
		抗法修炼 = 阶段属性[等级].修炼,
