		名称 = 怪物名称,
		模型 = 模型3[难度等级][2][取随机数(1, #模型3[难度等级][2])],
		伤害 = 伤害系数 * 阶段属性[等级].伤害 * 1,
		气血 = 气血系数 * 阶段属性[等级].气血 * 1 + 5000,
		灵力 = 灵力系数 * 阶段属性[等级].法伤 * 1,
