		法防 = 法防系数 * 阶段属性[等级].法防 * 0.6,
		躲避 = 阶段属性[等级].躲避,
		魔法 = 阶段属性[等级].魔法 * 99,
		攻击修炼 = 阶段属性[等级].修炼 / 2,
		防御修炼 = 阶段属性[等级].修炼,
		法术修炼 = 阶段属性[等级].修炼 / 2,
		抗法修炼 = 阶段属性[等级].修炼,
