			技能 = 被动,
			主动技能 = 主动 or {}
		}
	end

	战斗单位[1].召唤减少 = 0.8

	for i = 2, #战斗单位 do
		战斗单位[i].召唤减少 = 0.8

		if 抗物[战斗单位[i].模型] ~= nil then
			战斗单位[i].物伤减少 = 0.5
		elseif 抗法[战斗单位[i].模型] ~= nil then
			战斗单位[i].法伤减少 = 0.5
		elseif 双抗[战斗单位[i].模型] ~= nil then
			战斗单位[i].法伤减少 = 0.6
			战斗单位[i].物伤减少 = 0.6
			战斗单位[i].气血 = qz(战斗单位[i].气血 * 0.8)
		end
	end

	return 全局战斗难度调整(战斗单位)
end

