	local 战斗单位 = {
		阵法 = 阵法名称[取随机数(2, #阵法名称)]
	}
	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id)
	战斗单位[1] = {
		愤怒 = 99999,
		法伤减少 = 0.9,
		角色 = true,
		不可封印 = true,
