			等级 = 等级,
			技能 = {
				"高级神佑复生"
			},
			主动技能 = 列表2加入到列表1({
				"金刚护法",
				"韦陀护法",
				"四海升平",
				"晶清诀",
				"罗汉金钟"
			}, 夜光随机恢复法术(3)),
			攻击修炼 = 阶段属性[等级].修炼 / 2,
			防御修炼 = 阶段属性[等级].修炼,
