			抗法修炼 = 阶段属性[等级].修炼
		}
	end

	for i = 10, 10 do
		local 造型 = Q_随机模型[取随机数(1, #Q_随机模型)]
		local 武器造型 = 取天罡星武器造型(造型)
		战斗单位[i] = {
			愤怒 = 9999,
			角色 = true,
			名称 = Q_天罡星名称[取随机数(1, #Q_天罡星名称)],
