			武器 = 取武器数据(武器造型.武器, 武器造型.级别),
			气血 = 阶段属性[等级].气血 * 3,
			魔法 = 阶段属性[等级].魔法 * 30,
			伤害 = 阶段属性[等级].伤害 * 1.5,
			灵力 = 阶段属性[等级].法伤 * 1,
			速度 = 阶段属性[等级].速度 * 1,
			防御 = 阶段属性[等级].防御 * 0.75,
			法防 = 阶段属性[等级].法防 * 1,
