			防御修炼 = 阶段属性[等级].修炼,
			法术修炼 = 阶段属性[等级].修炼 / 2,
			抗法修炼 = 阶段属性[等级].修炼
		}
	end

	return 全局战斗难度调整(战斗单位, 0.95)
end

