取平均阶段等级 = function(玩家id)
	if 玩家数据[玩家id].队伍 == nil then
		return qz1(玩家数据[玩家id].角色.数据.等级 / 10) * 10
	end

	return qz1(取队伍平均等级(玩家数据[玩家id].队伍, 玩家id) / 10) * 10
end

