	local 人数 = 取队伍人数(玩家id)

	if 人数 == 1 then
		人数 = 5
	elseif 人数 == 5 then
		人数 = 取随机数(9, 10)
	elseif 人数 >= 3 then
		人数 = 取随机数(6, 10)
	else
		人数 = 取随机数(4, 10)
	end

	for i = 2, 人数 do
		模型 = 模型库2[取随机数(1, #模型库2)]
		技能随机 = 技能范围[取随机数(1, #技能范围)]
		战斗单位[i] = {
			显示饰品 = true,
			愤怒 = 9999,
			名称 = 模型 .. 模型名称范围[取随机数(1, #模型名称范围)],
			模型 = 模型,
			气血 = 阶段属性[等级].气血 * 0.5/1.6,
			魔法 = 阶段属性[等级].魔法 * 10/1.6,
			伤害 = 阶段属性[等级].伤害 * 0.8/1.6,
			灵力 = 阶段属性[等级].法伤 * 0.9/1.6,
			速度 = 阶段属性[等级].速度 * 0.45/1.6,
			防御 = 阶段属性[等级].防御 * 0.05/1.6,
			法防 = 阶段属性[等级].法防 * 0.05,
			躲避 = 阶段属性[等级].躲避 * 0.5/1.6,
			等级 = 等级,
			技能 = 列表2加入到列表1({
				"夜战"
			}, 取低级要诀(3)),
			主动技能 = 技能随机
		}
	end

	return 全局战斗难度调整(战斗单位)
end
