	local 等级 = 145

	print(阶段属性[等级].气血)

	战斗单位.阵法 = 假人随机阵法[取随机数(1, #假人随机阵法)]

	for i = 1, #假人属性 do
		if 假人属性[i].门派 ~= nil then
			local 临时数据 = self:取剑会天下随机属性1(假人属性[i].门派, 假人属性[i].等级)
			local 武器数据 = 取可佩带武器名称1(临时数据.模型, 假人属性[i].等级)
			战斗单位[i] = {
				愤怒 = 99999,
				名称 = 假人属性[i].名称,
				模型 = 临时数据.模型,
				气血 = 阶段属性[等级].气血 * 1,
				魔法 = 阶段属性[等级].魔法 * 10,
				伤害 = 阶段属性[等级].伤害 * 1,
				灵力 = 阶段属性[等级].法伤 * 1,
				速度 = 阶段属性[等级].速度 * 1,
				防御 = 阶段属性[等级].防御 * 0.5,
				法防 = 阶段属性[等级].法防 * 0.5,
				躲避 = 阶段属性[等级].躲避 * 1.2,
				等级 = 等级,
				技能 = {},
				主动技能 = 临时数据.技能,
				位置 = 假人属性[i].位置,
				攻击修炼 = 阶段属性[等级].修炼,
				防御修炼 = 阶段属性[等级].修炼,
				法术修炼 = 阶段属性[等级].修炼,
