				攻击修炼 = 阶段属性[等级].修炼,
				防御修炼 = 阶段属性[等级].修炼,
				法术修炼 = 阶段属性[等级].修炼,
				抗法修炼 = 阶段属性[等级].修炼,
				角色分类 = 假人属性[i].角色分类,
				五维属性 = 假人属性[i].五维属性,
				内丹数据 = 假人属性[i].内丹数据,
				追加法术 = 临时数据.追加法术
			}
		end
	end

	return 全局战斗难度调整(战斗单位)
end

