	local 模型名称范围 = {
		"喽罗"
	}
	local 技能范围 = {
		{
			"横扫千军",
			"善恶有报"
		},
		{
			"三昧真火",
			"地狱烈火",
			"飞砂走石"
		},
		{
			"龙卷雨击",
			"龙腾",
			"二龙戏珠"
		},
		{
			"落叶萧萧",
			"泰山压顶",
			"奔雷咒"
		},
		{
			"失心符",
			"定身符",
			"反间之计"
		},
		{
			"推气过宫"
		},
		{
			"天雷斩"
		}
	}
	local 技能随机 = 技能范围[取随机数(1, #技能范围)]

	for i = 2, 10 do
		local 模型 = Q_随机模型[取随机数(1, 5)]

		if 玩家数据[玩家id].角色.数据.种族 == "仙" then
			模型 = Q_随机模型[取随机数(6, 10)]
		elseif 玩家数据[玩家id].角色.数据.种族 == "魔" then
			模型 = Q_随机模型[取随机数(11, 15)]
		end

		武器造型 = 取天罡星武器造型(模型)
		技能随机 = 技能范围[取随机数(1, #技能范围)]
		战斗单位[i] = {
			气血 = 100000,
			角色 = true,
			魔法 = 200000,
