		"雷绝阵"
	}
	local 通天塔层数 = 通天塔数据[玩家id].层数
	local 等级 = 取队伍最高等级数(玩家数据[玩家id].队伍, 玩家id)

	if 通天塔层数 == nil then
		通天塔层数 = 0
	end

	if 通天塔层数 >= 0 and 通天塔层数 < 9999 then
		self.难度系数 = 1 + 通天塔层数 / 15
	end

	if 通天塔层数 >= 10000 and 通天塔层数 < 15000 then
			self.难度系数 = 1 + 通天塔层数 / 10
	end
	if 通天塔层数 >= 15001 and 通天塔层数 < 20000 then
		self.难度系数 = 1 + 通天塔层数 / 5
	end
	if 通天塔层数 >= 20001 and 通天塔层数 < 30000 then
		self.难度系数 = 1 + 通天塔层数 *1.1
