function 战斗准备类:取贼王的线索信息(任务id, 玩家id)
	local 战斗单位 = {}
	local 等级 = 取队伍平均等级(玩家数据[玩家id].队伍, 玩家id)
	local 数量 = 2 + 取队伍人数(玩家id)

	for n = 1, 数量 do
		战斗单位[n] = {
			气血 = 30000,
			魔法 = 99999900,
			灵力 = 3500,
			速度 = 500,
			伤害 = 1000,
			模型 = "骷髅怪",
			名称 = "帮凶",
			等级 = 175,
			防御 = 等级 * 3,
			法防 = 等级 * 3,
			躲避 = 等级 * 2,
			攻击修炼 = math.floor(取人物修炼等级上限1(等级)),
			防御修炼 = math.floor(取人物修炼等级上限1(等级)),
			法术修炼 = math.floor(取人物修炼等级上限1(等级)),
			抗法修炼 = math.floor(取人物修炼等级上限1(等级)),
			技能 = {
				"高级感知"
			},
			主动技能 = 取随机法术(4)
		}
	end

	战斗单位[1] = {
		气血 = 30000,
		魔法 = 99999900,
		灵力 = 3500,
		速度 = 500,
		伤害 = 1000,
		模型 = "吸血鬼",
		名称 = "贼王",
		等级 = 175,
		防御 = 等级 * 3,
		法防 = 等级 * 3,
		躲避 = 等级 * 2,
		攻击修炼 = math.floor(取人物修炼等级上限1(等级)),
