	local 技能范围 = {
		{
			"横扫千军",
			"善恶有报"
		},
		{
			"三昧真火",
			"地狱烈火",
			"飞砂走石"
		},
		{
			"龙卷雨击",
			"龙腾",
			"龙吟"
		},
		{
			"落叶萧萧",
			"雷击",
			"奔雷咒"
		},
		{
			"失心符",
			"定身符",
			"反间之计"
		},
		{
			"推气过宫"
		},
		{
			"天雷斩"
		}
